const CITIES: Record<string, { name: string; slug: string }[]> = {
  bihar: [
    { name: "Patna", slug: "patna" },
    { name: "Gaya", slug: "gaya" }
  ],
  maharashtra: [
    { name: "Pune", slug: "pune" },
    { name: "Mumbai", slug: "mumbai" }
  ]
};

export default function StatePage({ params }: { params: { state: string } }) {
  const { state } = params;
  const cities = CITIES[state] || [];

  return (
    <div className="min-h-screen p-4">
      <h1 className="text-lg font-semibold mb-4 capitalize">
        Cities in {state}
      </h1>

      <div className="space-y-3">
        {cities.map(city => (
          <a
            key={city.slug}
            href={`/${state}/${city.slug}`}
            className="block rounded-xl border p-4 text-center"
          >
            {city.name}
          </a>
        ))}
      </div>
    </div>
  );
}
